(() => {'use strict';
const $=s=>document.querySelector(s),e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected=null;
const names={needs_capture_review:'等待影片审核',needs_recapture:'需要补拍',accepted:'影片通过',modeling:'建模中',ready:'已完成',rejected:'已拒绝',queued:'等待处理',extracting_frames:'抽帧',features:'提取特征',matching:'匹配视角',sparse_reconstruction:'稀疏重建',dense_reconstruction:'稠密重建',scale_review:'尺度审核',stopped:'暂停',placed:'已下单',printing:'制作中',shipped:'已寄出',delivered:'已送达',cancelled:'已取消',pending:'待处理',submitted:'待审核',confirmed:'已确认',paid:'已付款'};
const label=x=>names[x]||x;
const api=async(path,options={})=>{const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});const d=await response.json().catch(()=>({}));if(!response.ok){if(response.status===401)showAuth();throw Error(d.detail?.code||response.status);}return d;};
const send=(path,d,method='PATCH')=>api(path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});
const options=(values,current)=>values.map(x=>`<option value="${e(x)}"${x===current?' selected':''}>${e(label(x))}</option>`).join('');
const message=err=>{const map={INVALID_CREDENTIALS:'账号或密码错误。',TOO_MANY_ATTEMPTS:'尝试次数过多，请稍后重试。',PAYMENT_NOT_CONFIRMED:'请先审核并确认付款。',INVALID_ORDER_TRANSITION:'订单状态不能这样跳转，请依次更新制作、寄出、送达。',TRACKING_REQUIRED:'寄出时必须填写物流公司和追踪号。',INVALID_AMOUNT:'报价必须是大于 0 的金额，最多两位小数。',ALREADY_PAID:'订单已经确认付款。'};return map[err.message]||'操作失败：'+err.message;};
function showAuth(){$('#admin-auth').hidden=false;$('#admin-workspace').hidden=true;$('#admin-logout').hidden=true;}
async function start(){$('#admin-auth').hidden=true;$('#admin-workspace').hidden=false;$('#admin-logout').hidden=false;await users();api('/api/internal/worker-status').then(()=>$('#local-operator-state').textContent='Mac 工作流在线，可远程操作。').catch(()=>$('#local-operator-state').textContent='Mac 工作流离线；云端任务与订单仍可管理。');}
async function users(q=''){const result=await api('/api/admin/users?q='+encodeURIComponent(q));$('#admin-users').innerHTML=result.items.length?result.items.map(u=>`<button class="user-choice${u.id===selected?' active':''}" data-id="${u.id}"><strong>${e(u.username)}</strong><small>${e(u.email)}</small><small>${u.design_count} 个设计 · ${u.order_count} 笔订单</small></button>`).join(''):'暂无用户。';$('#admin-users').querySelectorAll('button').forEach(b=>b.onclick=()=>detail(Number(b.dataset.id)).catch(err=>$('#admin-status').textContent=message(err)));}
function designCard(d){return `<article class="account-card"><h2>设计 ${e(d.id.slice(0,8))} · ${e(label(d.status))}</h2><p>${e(d.created_at)}<br>样式 ${e(d.template_id)} · ${e(d.color)} · ${e(d.material)}</p><p>灵感：${e(d.inspiration||'—')}</p><div class="record-actions"><a href="${e(d.video_url)}">下载原视频</a>${d.inspiration_url?`<a href="${e(d.inspiration_url)}">下载灵感图</a>`:''}${d.model_url?`<a href="${e(d.model_url)}">下载模型</a>`:''}</div><details><summary>更新状态与报价</summary><form class="record-form design-review" data-id="${e(d.id)}"><label>设计状态<select name="status">${options(['needs_capture_review','needs_recapture','accepted','modeling','ready','rejected'],d.status)}</select></label><label>建模阶段<select name="model_stage">${options(['queued','extracting_frames','features','matching','sparse_reconstruction','dense_reconstruction','scale_review','modeling','ready','stopped'],d.model_stage)}</select></label><label>报价（HKD，留空则不开放下单）<input name="quote_hkd" type="number" min="0.01" step=".01" value="${e(d.quote_hkd)}"></label><label>给用户的备注<textarea name="admin_note" maxlength="2000">${e(d.admin_note)}</textarea></label><button class="button button-dark">保存并记录历史</button></form><form class="model-upload" data-id="${e(d.id)}"><label>上传已生成模型（GLB / STL / 3MF，最大 100 MB）<input name="model" type="file" accept=".glb,.stl,.3mf" required></label><button class="button button-dark">上传模型</button></form></details><details><summary>建模历史（${d.events.length} 条）</summary>${d.events.map(x=>`<p>${e(x.created_at)} · ${e(label(x.status))} / ${e(label(x.stage))}<br>${e(x.note)}</p>`).join('')}</details></article>`;}
function orderCard(o){const d=o.delivery||{};return `<article class="account-card"><h2>订单 ${e(o.order_number)}</h2><p>HK$ ${e(o.amount_hkd)} · ${e(label(o.payment_status))} · ${e(label(o.order_status))}</p><p>收件人：${e(d.recipient_name)} · ${e(d.recipient_phone)}<br>地址：${e(d.region)} ${e(d.district)} ${e(d.address_line)}<br>备注：${e(d.delivery_note||'—')}</p><p>用户确认收货：${e(d.confirmed_at||'尚未确认')}</p><details open><summary>付款记录（${o.payments.length}）</summary>${o.payments.map(p=>`<div class="payment-record"><p>${e(p.created_at)} · ${e(p.method)} · ${e(p.reference)} · ${e(label(p.status))}</p>${p.proof_url?`<a href="${e(p.proof_url)}">下载付款凭证</a>`:'尚未上传凭证'}<p>${e(p.review_note||'')}</p>${p.status==='submitted'?`<form class="payment-review" data-id="${e(p.id)}"><label>审核结果<select name="status">${options(['confirmed','rejected'],'confirmed')}</select></label><label>审核备注<textarea name="review_note" maxlength="1000"></textarea></label><button class="button button-dark">保存付款审核</button></form>`:''}</div>`).join('')}</details><form class="record-form order-update" data-id="${e(o.id)}"><label>订单状态<select name="order_status">${options(['placed','modeling','printing','shipped','delivered','cancelled'],o.order_status)}</select></label><label>物流公司<input name="carrier" maxlength="100" value="${e(d.carrier)}"></label><label>物流追踪号<input name="tracking_number" maxlength="120" value="${e(d.tracking_number)}"></label><button class="button button-dark">更新配送</button></form></article>`;}
async function detail(id){selected=id;const d=await api('/api/admin/users/'+id);$('#admin-detail').innerHTML=`<section class="account-card"><h2>${e(d.user.username)}</h2><p>${e(d.user.email)}<br>姓名：${e(d.user.full_name||'—')} · 电话：${e(d.user.phone||'—')}<br>注册：${e(d.user.created_at)}</p></section><h2>建模记录</h2>${d.submissions.map(designCard).join('')||'<p>暂无设计。</p>'}<h2>订单、付款与收货</h2>${d.orders.map(orderCard).join('')||'<p>暂无订单。</p>'}`;
 const bind=(selector,path)=>$('#admin-detail').querySelectorAll(selector).forEach(form=>form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;$('#admin-status').textContent='正在保存…';try{await send(path(form.dataset.id),Object.fromEntries(new FormData(form)));await detail(selected);$('#admin-status').textContent='已保存。';}catch(err){$('#admin-status').textContent=message(err);button.disabled=false;}});
 bind('.design-review',id=>'/api/admin/submissions/'+id);bind('.payment-review',id=>'/api/admin/payments/'+id);bind('.order-update',id=>'/api/admin/orders/'+id);
 $('#admin-detail').querySelectorAll('.model-upload').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const file=form.elements.model.files[0],button=form.querySelector('button');button.disabled=true;try{if(!file||file.size>100*1024**2)throw Error('模型超过 100 MB');await api('/api/admin/submissions/'+form.dataset.id+'/model',{method:'PUT',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});await detail(selected);$('#admin-status').textContent='模型已保存。';}catch(err){$('#admin-status').textContent=message(err);button.disabled=false;}});
 $('#admin-users').querySelectorAll('.user-choice').forEach(b=>b.classList.toggle('active',Number(b.dataset.id)===id));
}
$('#admin-login').onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;try{await send('/api/admin/login',Object.fromEntries(new FormData(event.currentTarget)),'POST');await start();}catch(err){$('#admin-login-error').textContent=message(err);}finally{button.disabled=false;}};
$('#admin-logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST'});showAuth();};
$('#user-search').onsubmit=event=>{event.preventDefault();users(event.currentTarget.elements.q.value).catch(err=>$('#admin-status').textContent=message(err));};
api('/api/admin/session').then(start).catch(()=>showAuth());
})();
